	"github.com/santhosh-tekuri/jsonschema/v5"
)

func TestBenchmarkEvidenceFixturesValidate(t *testing.T) {
	schema := compileBenchmarkEvidenceSchema(t)

	validate := func(name string) map[string]any {
		t.Helper()
		doc := loadBenchmarkEvidenceFixture(t, name)
		if err := schema.Validate(doc); err != nil {
			t.Fatalf("%s failed schema validation: %v", name, err)
		}
		return doc
	}

	frontier := validate("managed-frontier-opus.json")
	assertString(t, frontier, "subject.model_raw", "Opus 4.7")
	assertString(t, frontier, "subject.harness", "claude-code")
	assertString(t, frontier, "subject.provider", "anthropic")
	assertString(t, frontier, "benchmark.subset_id", "tb2-wide")
	assertString(t, frontier, "benchmark.subset_version", "v2")
	assertString(t, frontier, "provenance.harness_wrapper_name", "claude-code")
	assertString(t, frontier, "provenance.harness_wrapper_version", "1.0.0")
	assertString(t, frontier, "provenance.provider_capture_at", "2026-05-06T20:00:00Z")
	assertString(t, frontier, "provenance.model_snapshot", "opus-4.7-20260505")
	assertString(t, frontier, "coverage.formula_version", "fhi/v1")

	local := validate("local-omlx-qwen.json")
	assertString(t, local, "subject.model_raw", "Qwen3.6-27B-MLX-8bit")
	assertString(t, local, "subject.provider", "omlx")
	assertString(t, local, "subject.endpoint", "http://vidar:1235/v1")
	assertString(t, local, "runtime.deployment_class", "local")
	assertString(t, local, "runtime.quantization", "8-bit")
	assertString(t, local, "runtime.local_runtime_name", "omlx")
	assertString(t, local, "runtime.local_runtime_version", "0.8.10")
	assertString(t, local, "runtime.hardware_class", "Mac Studio")
	assertString(t, local, "provenance.fizeau_version", "0.1.0")
	assertString(t, local, "provenance.fizeau_git_commit", "fa48595c7262b1522ab41897c3f60e128014f598")
	assertString(t, local, "provenance.provider_version", "0.8.10")
	assertString(t, local, "provenance.session_log_path", "benchmark-results/evidence/local-omlx-qwen/session.log.jsonl")
	assertString(t, local, "provenance.session_log_sha256", "3333333333333333333333333333333333333333333333333333333333333333")
	assertString(t, local, "benchmark.subset_id", "tb2-wide")
	assertString(t, local, "benchmark.subset_version", "v2")

	invalid := validate("invalid-run.json")
	assertString(t, invalid, "invalid_class", "invalid_setup")
	assertBool(t, invalid, "denominator.included", false)
	assertString(t, invalid, "denominator.policy", "exclude_invalid_runs")
	assertString(t, invalid, "denominator.reason", "setup failure before first benchmark task")
	assertString(t, invalid, "scope.denominator_rule", "exclude_invalid_runs")
}

func compileBenchmarkEvidenceSchema(t *testing.T) *jsonschema.Schema {
	t.Helper()

	repoRoot := benchRepoRoot(t)
	rawSchema, err := os.ReadFile(filepath.Join(repoRoot, "scripts", "benchmark", "benchmark-evidence.schema.json"))
	if err != nil {
		t.Fatalf("read benchmark evidence schema: %v", err)
	}

	compiler := jsonschema.NewCompiler()
	compiler.AssertFormat = true
	if err := compiler.AddResource("benchmark-evidence.schema.json", bytes.NewReader(rawSchema)); err != nil {
		t.Fatalf("add benchmark evidence schema: %v", err)
	}
	schema, err := compiler.Compile("benchmark-evidence.schema.json")
	if err != nil {
		t.Fatalf("compile benchmark evidence schema: %v", err)
	}
	return schema
}

func loadBenchmarkEvidenceFixture(t *testing.T, name string) map[string]any {
	t.Helper()

	repoRoot := benchRepoRoot(t)
	raw, err := os.ReadFile(filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", name))
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}

	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var doc map[string]any
	if err := dec.Decode(&doc); err != nil {
		t.Fatalf("parse fixture %s: %v", name, err)
	}
	return doc
}

func assertString(t *testing.T, doc map[string]any, path, want string) {
	t.Helper()
	got, ok := lookupPath(doc, path)
	if !ok {
		t.Fatalf("missing %s", path)
	}
	str, ok := got.(string)
	if !ok {
		t.Fatalf("%s = %T, want string", path, got)
	}
	if str != want {
		t.Fatalf("%s = %q, want %q", path, str, want)
	}
}

func assertBool(t *testing.T, doc map[string]any, path string, want bool) {
	t.Helper()
	got, ok := lookupPath(doc, path)
	if !ok {
		t.Fatalf("missing %s", path)
	}
	b, ok := got.(bool)
	if !ok {
		t.Fatalf("%s = %T, want bool", path, got)
	}
	if b != want {
		t.Fatalf("%s = %t, want %t", path, b, want)
	}
}

func lookupPath(doc map[string]any, path string) (any, bool) {
	var cur any = doc
	for _, segment := range bytes.Split([]byte(path), []byte(".")) {
		m, ok := cur.(map[string]any)
		if !ok {
			return nil, false
		}
		next, ok := m[string(segment)]
		if !ok {
			return nil, false
		}
		cur = next
	}
	return cur, true
}

package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	fizeau "github.com/DocumentDrivenDX/fizeau"
	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/external/termbench"
	agentConfig "github.com/DocumentDrivenDX/fizeau/internal/config"
)

// termbenchSubsetEntry is one row from scripts/beadbench/external/termbench-subset.json.
type termbenchSubsetEntry struct {
	ID         string   `json:"id"`
	Category   string   `json:"category,omitempty"`
	Difficulty string   `json:"difficulty,omitempty"`
	Tags       []string `json:"tags,omitempty"`
	Rationale  string   `json:"rationale,omitempty"`
}

type termbenchSubset struct {
	Version       string                 `json:"version"`
	Captured      string                 `json:"captured"`
	Dataset       string                 `json:"dataset"`
	DatasetRepo   string                 `json:"dataset_repo"`
	DatasetCommit string                 `json:"dataset_commit"`
	SelectionRule string                 `json:"selection_rule"`
	Tasks         []termbenchSubsetEntry `json:"tasks"`
}

// termbenchTaskRunSummary is one row in benchmark-results/termbench/<run>/results.json.
// Fields chosen to be reporter-friendly (jq, simple table renderers).
type termbenchTaskRunSummary struct {
	TaskID       string  `json:"task_id"`
	Category     string  `json:"category,omitempty"`
	Difficulty   string  `json:"difficulty,omitempty"`
	Harness      string  `json:"harness"`
	Model        string  `json:"model"`
	ExitCode     int     `json:"exit_code"`
	DurationMS   int64   `json:"duration_ms"`
	InputTokens  int     `json:"input_tokens"`
	OutputTokens int     `json:"output_tokens"`
	CostUSD      float64 `json:"cost_usd"`
	Reward       *int    `json:"reward,omitempty"` // nil = not graded yet
	Status       string  `json:"status"`           // ran|skipped|error|graded
	Error        string  `json:"error,omitempty"`
	Trajectory   string  `json:"trajectory_path,omitempty"`
}

type termbenchRunReport struct {
	RunID     string                    `json:"run_id"`
	StartedAt time.Time                 `json:"started_at"`
	Subset    string                    `json:"subset_path"`
	TasksDir  string                    `json:"tasks_dir"`
	Harness   string                    `json:"harness"`
	Model     string                    `json:"model"`
	Results   []termbenchTaskRunSummary `json:"results"`
	Notes     []string                  `json:"notes,omitempty"`
}

// runExternalTermbench is the cmd/bench entry point for `--external=termbench`.
// It is invoked from cmdRun when the flag is set; see runner.go.
//
// What it does:
//
//  1. Loads the frozen subset manifest (default
//     scripts/beadbench/external/termbench-subset.json).
//  2. For each entry, locates the upstream task directory under
//     scripts/benchmark/external/terminal-bench(-2)/tasks/<id>/.
//  3. Builds an ExecutionPlan and feeds it to fizeau.Service.Execute.
//  4. Captures harness events into ATIF v1.4 trajectory and writes
//     them to benchmark-results/termbench/<run-id>/<task>/logs/agent/.
//  5. Reads any verifier output (reward.txt) the upstream grader has
//     placed in the same directory and folds the verdict into the
//     report. We do NOT run the grader ourselves — running pytest in
//     the task's Docker image is upstream's responsibility (see SD-008).
//
// On a clean machine with no Docker stack, runs will complete with
// status=ran and no reward — that is the honest outcome the bead
// describes ("don't fake passing tests").
func runExternalTermbench(opts externalRunOptions) int {
	tasksDir := opts.tasksDir
	if tasksDir == "" {
		// terminal-bench-2 layout: task directories live at the repo
		// root (each task is a top-level directory), not under tasks/.
		// SD-008 §1 records this. The legacy TB1 path is also probed.
		candidates := []string{
			filepath.Join(opts.workDir, "scripts", "benchmark", "external", "terminal-bench-2"),
			filepath.Join(opts.workDir, "scripts", "benchmark", "external", "terminal-bench", "tasks"),
		}
		for _, c := range candidates {
			if _, err := os.Stat(c); err == nil {
				tasksDir = c
				break
			}
		}
	}
	subsetPath := opts.subsetPath
	if subsetPath == "" {
		subsetPath = filepath.Join(opts.workDir, "scripts", "beadbench", "external", "termbench-subset.json")
	}

	subset, err := loadTermbenchSubset(subsetPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s run --external=termbench: load subset %s: %v\n", benchCommandName(), subsetPath, err)
		return 1
	}

	// Build the agent service once; reuse across tasks.
	cfg, err := agentConfig.Load(opts.workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s run --external=termbench: load config: %v\n", benchCommandName(), err)
		return 1
	}
	svc, err := fizeau.New(fizeau.ServiceOptions{
		ServiceConfig: &configAdapter{cfg: cfg, workDir: opts.workDir},
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s run --external=termbench: new service: %v\n", benchCommandName(), err)
		return 1
	}

	runID := fmt.Sprintf("termbench-%d", time.Now().Unix())
	outBase := filepath.Join(opts.workDir, "benchmark-results", "termbench", runID)
	if err := os.MkdirAll(outBase, 0o750); err != nil {
		fmt.Fprintf(os.Stderr, "%s run --external=termbench: mkdir: %v\n", benchCommandName(), err)
		return 1
	}

	report := termbenchRunReport{
		RunID:     runID,
		StartedAt: time.Now().UTC(),
		Subset:    subsetPath,
		TasksDir:  tasksDir,
		Harness:   opts.harness,
		Model:     opts.model,
	}

	maxTasks := opts.maxTasks
	if maxTasks <= 0 || maxTasks > len(subset.Tasks) {
		maxTasks = len(subset.Tasks)
	}

	for i, entry := range subset.Tasks[:maxTasks] {
		summary := termbenchTaskRunSummary{
			TaskID:     entry.ID,
			Category:   entry.Category,
			Difficulty: entry.Difficulty,
			Harness:    opts.harness,
			Model:      opts.model,
		}
		taskOutDir := filepath.Join(outBase, entry.ID)
		taskDir := filepath.Join(tasksDir, entry.ID)
		if _, err := os.Stat(taskDir); err != nil {
			summary.Status = "skipped"
			summary.Error = fmt.Sprintf("task dir not found: %s (submodule not initialized?)", taskDir)
			report.Results = append(report.Results, summary)
			fmt.Fprintf(os.Stderr, "[%d/%d] %s: %s\n", i+1, maxTasks, entry.ID, summary.Error)
			continue
		}
		task, err := termbench.LoadTask(taskDir)
		if err != nil {
			summary.Status = "error"
			summary.Error = err.Error()
			report.Results = append(report.Results, summary)
			fmt.Fprintf(os.Stderr, "[%d/%d] %s: load task: %v\n", i+1, maxTasks, entry.ID, err)
			continue
		}
		if err := os.MkdirAll(taskOutDir, 0o750); err != nil {
			summary.Status = "error"
			summary.Error = err.Error()
			report.Results = append(report.Results, summary)
			continue
		}
		// For the Go-side dry-run we operate the agent against a fresh
		// per-task tempdir. Real Harbor runs would mount the container
		// workspace; here we just need a writable cwd for the fizeau.
		workDir, err := os.MkdirTemp("", "termbench-"+entry.ID+"-")
		if err != nil {
			summary.Status = "error"
			summary.Error = err.Error()
			report.Results = append(report.Results, summary)
			continue
		}
		defer os.RemoveAll(workDir)

		plan := termbench.BuildPlan(task, termbench.PlanOptions{
			Harness:     opts.harness,
			Provider:    opts.provider,
			Model:       opts.model,
			WorkDir:     workDir,
			Permissions: opts.permissions,
		})
		ctx, cancel := context.WithTimeout(context.Background(), plan.Timeout)
		start := time.Now()
		ch, err := svc.Execute(ctx, plan.Request)
		if err != nil {
			cancel()
			summary.Status = "error"
			summary.Error = err.Error()
			summary.DurationMS = time.Since(start).Milliseconds()
			report.Results = append(report.Results, summary)
			fmt.Fprintf(os.Stderr, "[%d/%d] %s: execute: %v\n", i+1, maxTasks, entry.ID, err)
			continue
		}
		traj := termbench.Capture(ch, termbench.CaptureOptions{
			SessionID: runID + "/" + entry.ID,
			TaskID:    entry.ID,
			Agent: termbench.AgentInfo{
				Name:      opts.harness,
				Version:   "bench",
				ModelName: opts.model,
			},
			StartedAt: start,
